<?phpnamespace app\webscoket;use Swoole\Table as SwooleTable;use think\swoole\Table;class SocketPush{    /**     * @var static     */    protected static $instance;    protected $userType;    protected $toId;    protected $type;    protected $data;    /**     * 实例化本类     */    public static function instance()    {        if (is_null(self::$instance)) {            self::$instance = new self();        }        return self::$instance;    }    public function setUserType($type){        $this->userType=$type;    }    //发送给谁    public function to($fd){        $this->toId=$fd;    }    //类型    public function type($type){        $this->type=$type;    }    //数据    public function data($data){        $this->data=$data;    }    //发送    public function push(){    }    public static function store(){        if (is_null(self::$instance)) {            self::$instance = new self();        }        return self::$instance;    }}